-- 갈래말래 추천용 음식 마스터 데이터 (MySQL 8.0+)
-- 프론트 menuMaster 8개 카테고리와 allergenOptions 22종을 기준으로 작성했다.
-- 메뉴별 알레르기는 대표 조리법 기준 더미데이터이며 실제 매장 조리법과 교차오염 여부를 대체하지 않는다.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS allergen (
    id BINARY(16) NOT NULL, name VARCHAR(255) NOT NULL, description VARCHAR(255) NULL,
    created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (id), UNIQUE KEY uk_allergen_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS food_category (
    id BINARY(16) NOT NULL, name VARCHAR(255) NOT NULL,
    created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (id), UNIQUE KEY uk_food_category_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS menu (
    id BINARY(16) NOT NULL, category_id BINARY(16) NOT NULL,
    name VARCHAR(255) NOT NULL, image_url VARCHAR(255) NULL,
    created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
    PRIMARY KEY (id), UNIQUE KEY uk_menu_name (name), KEY idx_menu_category_id (category_id),
    CONSTRAINT fk_menu_food_category FOREIGN KEY (category_id) REFERENCES food_category (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS menu_allergen (
    menu_id BINARY(16) NOT NULL, allergen_id BINARY(16) NOT NULL, created_at DATETIME(6) NOT NULL,
    PRIMARY KEY (menu_id, allergen_id), KEY idx_menu_allergen_allergen_id (allergen_id),
    CONSTRAINT fk_menu_allergen_menu FOREIGN KEY (menu_id) REFERENCES menu (id) ON DELETE CASCADE,
    CONSTRAINT fk_menu_allergen_allergen FOREIGN KEY (allergen_id) REFERENCES allergen (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

START TRANSACTION;

ON DUPLICATE KEY UPDATE description=VALUES(description), updated_at=NOW(6);

ON DUPLICATE KEY UPDATE name=VALUES(name), updated_at=NOW(6);

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), image_url=VALUES(image_url), updated_at=NOW(6);


COMMIT;

SELECT COUNT(*) AS allergen_count FROM allergen;
SELECT COUNT(*) AS category_count FROM food_category;
SELECT COUNT(*) AS menu_count FROM menu;
SELECT COUNT(*) AS menu_allergen_count FROM menu_allergen;
